input.command:
cd <run-dir>; cat > <scratch> <<'EOF'
.headers on
select * from fct_policy_premium limit 5;
select status,count(*),sum(premium_amt),sum(premium_amt_gross),sum(cancellation_amt) from fct_policy_premium group by 1;
select min(eff_dt),max(eff_dt),count(*),count(distinct policy_id),count(distinct premium_id) from fct_policy_premium;
select distinct length(eff_dt), substr(eff_dt,1,4) from fct_policy_premium;
select * from dim_geography;
select * from dim_product;
select * from dim_date limit 3;
select * from fct_claims limit 5;
select status,severity,count(*) from fct_claims group by 1,2;
select * from fct_commissions limit 5;
select min(paid_dt),max(paid_dt) from fct_commissions;
select count(*) from fct_policy_premium where geo_id not in (select geo_id from dim_geography) or geo_id is null;
select count(*) from fct_policy_premium where product_id not in (select product_id from dim_product) or product_id is null;
EOF
sqlite3 warehouse.db < <scratch>

