cd <run-dir>; cat > <scratch> <<'EOF'
.headers on
select g.region, round(sum(p.premium_amt - p.cancellation_amt),2) nwp, round(sum(p.premium_amt),2) nwp_before_canc, count(*) from fct_policy_premium p join dim_geography g using(geo_id)
 where p.status in ('written','cancelled') and p.eff_dt between '2026-07-01' and '2026-09-30' group by 1;
select d.product_line, round(sum(p.premium_amt_gross),2) gwp, count(*) from fct_policy_premium p join dim_product d using(product_id)
 where p.status in ('written','cancelled') and p.eff_dt between '2026-01-01' and '2026-06-30' group by 1;
select status, count(*) from fct_policy_premium where eff_dt like '2026-03-%' group by 1;
select severity, round(sum(paid_amt),2), count(*) from fct_claims where status='closed' and closed_dt between '2026-04-01' and '2026-06-30' group by 1;
select round(sum(commission_amt),2), count(*) from fct_commissions where paid_dt between '2026-07-01' and '2026-09-30';
select g.region, round(sum(c.claim_amt),2) inc, round(sum(c.paid_amt),2) paid from fct_claims c join fct_policy_premium p using(policy_id) join dim_geography g using(geo_id) where c.reported_dt between '2026-07-01' and '2026-09-30' group by 1;
EOF
sqlite3 warehouse.db < <scratch>

